# Prompt Contracts Lab -- REPAIR, not just detect.
CONTRACT_KEYS = {"answer", "refused", "sources"}


def repair_output(out, retrieved):
    good = [s for s in out.get("sources", []) if s in retrieved]
    if not out.get("refused") and out.get("answer") is not None and good:
        return {"answer": out["answer"], "refused": False, "sources": good}
    return {"answer": None, "refused": True, "sources": []}


RETRIEVED = {"doc1", "doc2", "doc3"}

CASES = [
    {"answer": "Paris is the capital.", "refused": False, "sources": ["doc1"]},
    {"answer": None, "refused": True, "sources": []},
    {"answer": "Made up fact.", "refused": False, "sources": ["doc9"]},
    {"answer": "Grounded but over-cited.", "refused": False, "sources": ["doc2", "doc9"]},
    {"answer": "Hedged answer.", "refused": True, "sources": ["doc1"]},
]

for i, case in enumerate(CASES):
    r = repair_output(case, RETRIEVED)
    ans = r["answer"] if r["answer"] is not None else "None"
    print(f"case {i}: refused={r['refused']} answer={ans} sources={r['sources']}")

