# Structured Outputs Lab -- the VALIDATION GATE Pydantic enforced, as a standalone
# invariant check over a batch of candidate decisions (the role a schema plays).
VALID_IDS = {"kb-01", "kb-02", "kb-03"}


def validate_decision(record, valid_ids):
    if record["amount_usd"] < 0:
        return "reject: negative amount"
    if record["approved"] and len(record["source_ids"]) < 1:
        return "reject: approved without citations"
    for sid in record["source_ids"]:
        if sid not in valid_ids:
            return f"reject: uncited source {sid}"
    return "ok"


CANDIDATES = [
    {"approved": True,  "amount_usd": 49.99, "reason": "within 30-day window", "source_ids": ["kb-01", "kb-02"]},
    {"approved": True,  "amount_usd": 0.0,   "reason": "policy",               "source_ids": []},
    {"approved": False, "amount_usd": -5.0,  "reason": "double refund",        "source_ids": []},
    {"approved": True,  "amount_usd": 20.0,  "reason": "ok",                   "source_ids": ["kb-01", "kb-99"]},
    {"approved": False, "amount_usd": 0.0,   "reason": "insufficient evidence","source_ids": []},
]

for i, cand in enumerate(CANDIDATES):
    print(f"candidate {i}: {validate_decision(cand, VALID_IDS)}")

