]


def make_chunk_id(source, version, section, index):
    return f"{source}#{version}#{section}#c{index:04d}"


def upsert_all(index, chunks):
    for i, chunk in enumerate(chunks):
        chunk_id = make_chunk_id(chunk["source"], chunk["version"], chunk["section"], i)
        index[chunk_id] = chunk["text"]


index = {}
upsert_all(index, run_v3)
upsert_all(index, reingest_v3)

print("chunk_count:", len(index))
for chunk_id in sorted(index):
    print(chunk_id, "->", index[chunk_id])

