# Retrieval quality lab -- DIAGNOSE the failure mode, not just score recall.
# recall@k gives one number. This turns the worked example's "reading" into code:
# for each query, find where the gold chunk landed and classify the miss.


class Chunk:
    def __init__(self, id):
        self.id = id


_RESULTS = {
    "What is the refund window?": [
        "faq_general#p1", "policy_refunds_v3#p2", "policy_returns#p7",
        "shipping_intl#p1", "billing_plans#p4", "policy_refunds_v3#p9",
    ],
    "Do you ship to Canada?": [
        "shipping_domestic#p3", "shipping_intl#p9", "faq_general#p1",
        "policy_refunds_v3#p2", "shipping_rates#p2", "shipping_intl#p1",
    ],
    "Can I change my plan mid-cycle?": [
        "billing_plans#p4", "billing_invoices#p1", "faq_billing#p2",
        "policy_refunds_v3#p2", "billing_plans#p9", "account_settings#p5",
    ],
}


def retrieve(question, k=6):
    ids = _RESULTS[question][:k]
    return [Chunk(i) for i in ids]


EVAL_SET = [
    {"q": "What is the refund window?", "gold_id": "policy_refunds_v3#p2"},
    {"q": "Do you ship to Canada?", "gold_id": "shipping_intl#p1"},
    {"q": "Can I change my plan mid-cycle?", "gold_id": "billing_plans#p4"},
]

FULL_DEPTH = 6


def gold_rank(question, gold_id):
    ids = [c.id for c in retrieve(question, k=FULL_DEPTH)]
    return ids.index(gold_id) + 1 if gold_id in ids else None


def diagnose_retrieval(eval_set, k):
    counts = {"hit@1": 0, "rerank-fixable": 0, "retrieval-miss": 0}
    for case in eval_set:
        rank = gold_rank(case["q"], case["gold_id"])
        if rank == 1:
            label = "hit@1"
        elif rank is not None and rank <= k:
            label = "rerank-fixable"
        else:
            label = "retrieval-miss"
        counts[label] += 1
        shown = rank if rank is not None else "none"
        print(f"{case['q']} -> gold rank {shown} @depth{FULL_DEPTH}: {label}")
    return counts


if __name__ == "__main__":
    counts = diagnose_retrieval(EVAL_SET, k=3)
    print(f"hit@1={counts['hit@1']} rerank-fixable={counts['rerank-fixable']} retrieval-miss={counts['retrieval-miss']}")

