# Tool-calling workflows lab -- the CONTROLLER: validate every proposed call AND
# enforce a per-session execution budget, emitting an auditable ledger. Validation
# alone is one gate; a runaway agent also needs a hard cap on how much it may DO.

KNOWN_TOOLS = {"search_docs", "refund_order"}


def dispatch(calls, user, budget):
    ledger = []
    executed = 0
    for name, args in calls:
        if name not in KNOWN_TOOLS:
            ledger.append(f"BLOCK {name}: unknown tool {name}")
            continue
        if name == "refund_order" and not user["can_refund"]:
            ledger.append(f"BLOCK {name}: unauthorized: user lacks refund scope")
            continue
        if name == "search_docs":
            if "query" not in args:
                ledger.append(f"BLOCK {name}: missing required arg: query")
                continue
            if len(args["query"]) > 300:
                ledger.append(f"BLOCK {name}: query too long (injection/cost guard)")
                continue
            if args.get("top_k", 5) > 20:
                ledger.append(f"BLOCK {name}: top_k over limit (DoS/cost guard)")
                continue
        if executed >= budget:
            ledger.append(f"BLOCK {name}: session call budget exhausted")
            continue
        executed += 1
        ledger.append(f"EXEC {name}")
    return ledger


CALLS = [
    ("search_docs", {"query": "reset password", "top_k": 5}),
    ("search_docs", {"query": "pricing"}),
    ("search_docs", {"query": "billing", "top_k": 3}),
    ("search_docs", {"top_k": 3}),
    ("search_docs", {"query": "x" * 301}),
    ("search_docs", {"query": "pricing", "top_k": 999}),
    ("refund_order", {"order_id": "A1"}),
    ("delete_db", {}),
]
USER = {"can_refund": False}
BUDGET = 2

if __name__ == "__main__":
    for line in dispatch(CALLS, USER, BUDGET):
        print(line)

agent-workflow-control.code:
# Agent workflow control lab -- TRACE the controlled loop, don't just verdict it.
# run_agent returned a decision; here you emit the ordered event log a reviewer
# reads to see WHY: which calls were dropped off-allowlist, which steps burned
# budget, and the exact step that answered or the refusal at the end.

ALLOWED_TOOLS = {"retrieve"}
MAX_STEPS = 4
GROUNDING_MIN = 0.35

PLANS = {
    "reset password": [
        ("web_search", 0.90), ("retrieve", 0.20), ("retrieve", 0.61), ("retrieve", 0.99),
    ],
    "company stock tip": [
        ("shell", 0.80), ("retrieve", 0.10), ("retrieve", 0.15), ("retrieve", 0.30),
    ],
    "office hours": [
        ("retrieve", 0.35), ("retrieve", 0.99),
    ],
}


def trace_agent(query):
    """Return the ordered list of control events for query's plan."""
    events = []
    steps = 0
    for tool, support in PLANS[query]:
        if tool not in ALLOWED_TOOLS:
            events.append(f"DROP {tool} (off-allowlist)")
            continue
        if steps >= MAX_STEPS:
            break
        steps += 1
        if support >= GROUNDING_MIN:
            events.append(f"STEP{steps} {tool} support={support} ANSWER")
            return events
        events.append(f"STEP{steps} {tool} support={support} weak")
    events.append(f"REFUSE after {steps} step(s)")
    return events


if __name__ == "__main__":
    for q in ["reset password", "company stock tip", "office hours"]:
        print(q + ":")
        for e in trace_agent(q):
            print("  " + e)
